pub fn solve(s: Vec<char>) -> Vec<char> {
    let mut buffer = Vec::new();
    for c in s {
        match c {
            '0' | '1' => buffer.push(c),
            'B' => {
                buffer.pop();
            }
            // Given the problem constraints, we won't see any other characters
            _ => {}
        }
    }
    buffer
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_only_digits() {
        let input = vec!['0', '1', '1', '0'];
        let output = solve(input);
        assert_eq!(output, vec!['0', '1', '1', '0']);
    }

    #[test]
    fn test_backspaces() {
        let input = vec!['1', '0', 'B', '1', 'B', 'B', '1'];
        // step by step:
        // "1" -> ['1']
        // "0" -> ['1','0']
        // "B" -> ['1']
        // "1" -> ['1','1']
        // "B" -> ['1']
        // "B" -> []
        // "1" -> ['1']
        let output = solve(input);
        assert_eq!(output, vec!['1']);
    }

    #[test]
    fn test_backspace_on_empty() {
        let input = vec!['B', 'B', '0', 'B', '1'];
        // initial "BB" does nothing, "0" -> ['0'], "B" -> [], "1" -> ['1']
        let output = solve(input);
        assert_eq!(output, vec!['1']);
    }
}